import http from 'k6/http'; import {check} from 'k6'; import {Rate} from 'k6/metrics'; import {baseURL,scenarioOptions} from '../lib/config.js'; import {routeSuccess} from '../lib/metrics.js';
const cancellation=new Rate('sse_cancellation_success');export const options=scenarioOptions('sse',['route_success']);options.thresholds.sse_cancellation_success=['rate==1'];export default function(){const r=http.get(`${baseURL()}/sse`,{timeout:'5s',tags:{route_family:'sse',operation:'stream',expected_status:'200'}});const ok=check(r,{'sse status is 200':x=>x.status===200,'sse content type event-stream':x=>(x.headers['Content-Type']||'').includes('text/event-stream'),'sse cache control no-cache':x=>(x.headers['Cache-Control']||'').includes('no-cache'),'sse event id present':x=>x.body.includes('id:'),'sse event data present':x=>x.body.includes('data:'),'sse event boundary present':x=>x.body.includes('\n\n'),'sse heartbeat comment present':x=>x.body.includes(':'),'sse response bounded':x=>x.body.length<1048576,'sse duration honors cancellation':x=>x.timings.duration<=5000});routeSuccess.add(ok,r.tags);cancellation.add(r.timings.duration<=5000,r.tags);}
